mapper.sql:
WHERE t.completed_at IS NULL

    AND t.destination = #{destination}


    AND t.end_date >= #{dateFrom}


    AND t.start_date <= #{dateTo}


    AND (

        t.tags LIKE ('%"' || #{tag} || '"%')

    )


    AND LOWER(t.title || ' ' || t.destination || ' ' || t.stops || ' ' || t.tags || ' ' || u.nickname)
        LIKE ('%' || LOWER(#{q}) || '%')
